import type { SecurityCheck } from '@xdigitex/scanner-core';
export const clientCheck:SecurityCheck={id:'client.passive',name:'Client-side inspection',category:'Client-Side Analysis',async run(ctx){
 const out=[]; for(const url of ctx.scripts.slice(0,50)){ const r=await ctx.http.request(url); if(/\b(?:innerHTML|outerHTML|insertAdjacentHTML)\s*=|document\.write\s*\(/.test(r.body)) out.push({checkId:this.id,title:'Potentially unsafe DOM sink present',description:'A public JavaScript resource contains a DOM sink that may become security-sensitive when fed untrusted input. This is a code indicator, not confirmed XSS.',category:'XSS',severity:'INFORMATIONAL',confidence:'NEEDS_REVIEW',affectedUrl:r.url,method:'GET',impact:'If attacker-controlled data reaches this sink without contextual encoding, DOM XSS may become possible.',remediation:'Trace data flow to the sink and use safe DOM APIs or contextual sanitization.',evidence:[r.evidence]}); if(/sourceMappingURL=/.test(r.body)) out.push({checkId:this.id,title:'Source map reference exposed',description:'A JavaScript bundle references a source map.',category:'Information Disclosure',severity:'INFORMATIONAL',confidence:'CONFIRMED',affectedUrl:r.url,method:'GET',impact:'Source maps can reveal source structure and implementation details.',remediation:'Review whether production source maps should be public; restrict or omit them where appropriate.',evidence:[r.evidence]}); } return out;
}};
